-- ============================================================
-- 110: receptury (etapy + materiały + dawki) z kart Księgi Technicznej
-- dla technologii, które w ERP miały tylko wpis w `technologies`
-- (101 świadomie pominęło ich recepturę), plus 3 brakujące karty
-- (P/6, P/12, ST/PU/25).
--
-- Źródło: karty md w docs/ksiega-techniczna/ (z Dysku Google, folder
-- „00_Księga Techniczna Flowtex - poprawione"). Zasady:
--   * etap = warstwa z karty; materiał tylko tam, gdzie karta podaje
--     dawkę (kg/m², kg/mb, m³/mb); etapy bez dawki (nacięcia,
--     przygotowanie podłoża) zostają jako etapy bez materiałów,
--   * dawka jest wstawiana TYLKO gdy jej mianownik (m²/mb) zgadza się z
--     technologies.unit — inaczej pomijana (zużycie na m² w technologii
--     rozliczanej w mb dałoby błędny koszt); lista pominięć: NOTICE
--     podczas wykonania i docs/ksiega-techniczna/ZGODNOSC_Z_ERP.md,
--   * technologie, które JUŻ mają recepturę (etapy inne niż „Materiał główny"),
--     nie są ruszane — migracja jest idempotentna,
--   * „Materiał główny" (1 mb/mb) zakłada 106, tu pomijany,
--   * kg/dm³ (SikaGrout-314 w ACO/K/*, ACO/W/1) wpisane jako kg na
--     jednostkę technologii (2.2 kg/mb wg wzorca użytkownika) — do
--     potwierdzenia.
-- ============================================================

-- ---------- 3 brakujące technologie ----------
insert into technologies (code, name, company, is_active, version, unit) values
  ('P/6', 'Frezowanie podłoża i obróbka krawędziowa', null, true, 1, 'm2'),
  ('P/12', 'Wycinanie dwustronne kanału pod wymianę na nowy', null, true, 1, 'mb'),
  ('ST/PU/25', 'System posadzkowy Deckshield LBD 5-6mm (rampa)', 'Tremco CPG', true, 1, 'm2')
on conflict (code, version) do nothing;

insert into offer_pilot_technologies (technology_id, category_name, unit)
select id, 'P:0 - Przygotowanie Betonu', unit from technologies where code in ('P/6', 'P/12')
union all
select id, 'ST:0 - Systemy TREMCO', unit from technologies where code = 'ST/PU/25'
on conflict (technology_id) do nothing;

-- ---------- pomocnicza funkcja (usuwana na końcu) ----------
create or replace function _seed_recipe(p_code text, p_stages jsonb)
returns void
language plpgsql
as $$
declare
  v_t technologies%rowtype;
  v_stage jsonb;
  v_mat jsonb;
  v_stage_id integer;
  v_base integer;
  v_i integer := 0;
begin
  select * into v_t from technologies where code = p_code and is_active order by version desc limit 1;
  if v_t.id is null then
    raise notice '% : brak technologii w bazie - pominięto', p_code;
    return;
  end if;
  if exists (
    select 1 from technology_stages s
    where s.technology_id = v_t.id and s.name <> 'Materiał główny'
  ) then
    return; -- ma już etapy (receptura) - nie ruszamy
  end if;
  select coalesce(max(order_index), 0) into v_base from technology_stages where technology_id = v_t.id;
  for v_stage in select * from jsonb_array_elements(p_stages)
  loop
    v_i := v_i + 1;
    insert into technology_stages (technology_id, name, order_index)
    values (v_t.id, v_stage->>'stage', v_base + v_i) returning id into v_stage_id;
    for v_mat in select * from jsonb_array_elements(v_stage->'materials')
    loop
      if v_mat->>'req' is not null and v_mat->>'req' <> v_t.unit then
        raise notice '% / % : dawka % na % pominięta - technologia rozliczana w %',
          p_code, v_mat->>'name', v_mat->>'c', v_mat->>'req', v_t.unit;
      else
        insert into technology_materials (stage_id, material_name, unit, consumption_per_m2)
        values (v_stage_id, v_mat->>'name', v_mat->>'unit', (v_mat->>'c')::numeric);
      end if;
    end loop;
  end loop;
end;
$$;

